//! ProverResult
use alloc::string::String;
use alloc::string::ToString;
use alloc::vec::Vec;
use ergotree_ir::chain::context_extension::ContextExtension;
use ergotree_ir::serialization::sigma_byte_reader::SigmaByteRead;
use ergotree_ir::serialization::sigma_byte_writer::SigmaByteWrite;
use ergotree_ir::serialization::SigmaParsingError;
use ergotree_ir::serialization::SigmaSerializable;
use ergotree_ir::serialization::SigmaSerializationError;
use ergotree_ir::serialization::SigmaSerializeResult;

use core::convert::TryFrom;

/// Serialized proof generated by ['Prover']
#[derive(PartialEq, Eq, Hash, Debug, Clone)]
pub enum ProofBytes {
    /// Empty proof
    Empty,
    /// Non-empty proof
    Some(Vec<u8>),
}

impl ProofBytes {
    /// Returns bytes or empty vector if empty
    pub fn to_bytes(self) -> Vec<u8> {
        match self {
            ProofBytes::Empty => Vec::new(),
            ProofBytes::Some(bytes) => bytes,
        }
    }
}

impl From<ProofBytes> for Vec<u8> {
    fn from(v: ProofBytes) -> Self {
        match v {
            ProofBytes::Empty => Vec::new(),
            ProofBytes::Some(bytes) => bytes,
        }
    }
}

impl From<Vec<u8>> for ProofBytes {
    fn from(bytes: Vec<u8>) -> Self {
        if bytes.is_empty() {
            ProofBytes::Empty
        } else {
            ProofBytes::Some(bytes)
        }
    }
}

// for JSON encoding in ergo-lib as Base16-encoded string
impl From<ProofBytes> for String {
    fn from(v: ProofBytes) -> Self {
        match v {
            ProofBytes::Empty => "".to_string(),
            ProofBytes::Some(bytes) => base16::encode_lower(&bytes),
        }
    }
}

// for JSON encoding in ergo-lib
impl TryFrom<String> for ProofBytes {
    type Error = base16::DecodeError;

    fn try_from(value: String) -> Result<Self, Self::Error> {
        base16::decode(&value).map(|bytes| bytes.into())
    }
}

impl AsRef<[u8]> for ProofBytes {
    fn as_ref(&self) -> &[u8] {
        match self {
            ProofBytes::Empty => &[],
            ProofBytes::Some(bytes) => bytes.as_ref(),
        }
    }
}

impl SigmaSerializable for ProofBytes {
    fn sigma_serialize<W: SigmaByteWrite>(&self, w: &mut W) -> SigmaSerializeResult {
        match self {
            ProofBytes::Empty => w.put_u16(0)?,
            ProofBytes::Some(bytes) => {
                // sigmastate writes the length with `putUShort`, which refuses one above 65535
                // (v6.0.6 `ProverResult.scala:34`)
                let len = u16::try_from(bytes.len()).map_err(|_| {
                    SigmaSerializationError::NotSupported(format!(
                        "a proof of {} bytes is out of unsigned short range",
                        bytes.len()
                    ))
                })?;
                w.put_u16(len)?;
                w.write_all(bytes)?;
            }
        }
        Ok(())
    }

    fn sigma_parse<R: SigmaByteRead>(r: &mut R) -> Result<Self, SigmaParsingError> {
        let proof_len = r.get_u16()?;
        Ok(if proof_len == 0 {
            ProofBytes::Empty
        } else {
            let mut bytes = vec![0; proof_len as usize];
            r.read_exact(&mut bytes)?;
            ProofBytes::Some(bytes)
        })
    }
}

/// Proof of correctness of tx spending
#[derive(Debug, PartialEq, Eq, Clone)]
pub struct ProverResult {
    /// proof that satisfies final sigma proposition
    pub proof: ProofBytes,
    /// user-defined variables to be put into context
    pub extension: ContextExtension,
}

#[cfg(feature = "arbitrary")]
/// Arbitrary impl
mod arbitrary {
    use super::*;
    use proptest::{collection::vec, prelude::*};

    impl Arbitrary for ProofBytes {
        type Parameters = ();
        type Strategy = BoxedStrategy<Self>;

        fn arbitrary_with(_args: Self::Parameters) -> Self::Strategy {
            prop_oneof![
                Just(ProofBytes::Empty),
                (vec(any::<u8>(), 32..100))
                    .prop_map(ProofBytes::Some)
                    .boxed()
            ]
            .boxed()
        }
    }
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod proof_length_tests {
    //! sigmastate writes a proof's length with `putUShort`, which throws `Value N is out of
    //! unsigned short range` above 65535 (v6.0.6 `ProverResult.scala:34`; measured on the
    //! sigma-state 6.0.7 jars, the round's `measure/out/mem-jvm.txt`). The reader takes the
    //! length as an unsigned short, so only code (or JSON) gives a longer proof.
    use super::*;
    use ergotree_ir::serialization::SigmaSerializationError;

    #[test]
    fn a_proof_of_65535_bytes_is_written() {
        let bytes = ProofBytes::Some(vec![0; 65535])
            .sigma_serialize_bytes()
            .unwrap();
        // the length `ff ff 03`, the proof; the jars' `ProverResult` is one byte more, the count
        // of an empty context extension
        assert_eq!(bytes.len(), 3 + 65535);
        assert_eq!(bytes[..3], [0xff, 0xff, 0x03]);
    }

    #[test]
    fn a_proof_of_65536_bytes_is_refused() {
        let res = ProofBytes::Some(vec![0; 65536]).sigma_serialize_bytes();
        assert!(matches!(res, Err(SigmaSerializationError::NotSupported(_))));
    }
}
